var n=`0674-kedjenou`;var t=`world-0674`;var s=`CI`;var a=`western-africa`;var o=4;var r=121;var g={en:`Kedjenou`,ua:`Кеджену`};var d={en:`Kedjenou is a Côte d'Ivoire classic prepared with chicken thigh, yellow onion, garlic, ginger root. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Кеджену, страва кухні країни Кот-д'Івуар зі складниками: куряче стегно, жовта цибуля, часник, корінь імбиру. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`chicken-thigh`,790,`g`],[`yellow-onion`,260,`g`],[`garlic`,4,`clove`],[`ginger-root`,30,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`tomato`,300,`g`],[`eggplant`,220,`g`],[`okra`,220,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 75 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 75 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:75,i:[[`chicken-stock`,150,`ml`],[`red-palm-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`]]}];var h={slug:n,id:t,country:`CI`,region:a,servings:4,minutes:121,title:g,text:d,steps:l};export{s as country,h as default,t as id,r as minutes,a as region,o as servings,n as slug,l as steps,d as text,g as title};